package io.github.jackotom.hongguo.android;
import java.io.*;import java.net.*;import java.lang.reflect.*;import java.util.*;import java.util.concurrent.*;
/** Production guards with synthetic DNS and sockets only; no DNS/network traffic. */
public final class SourceDeadlineTest {
 static int checks,passed,failed; interface Work {void run()throws Exception;}
 static void check(boolean ok,String label){checks++;if(!ok)throw new AssertionError(label);}
 static void group(String name,Work work){try{work.run();passed++;System.out.println("PASS "+name);}catch(Throwable error){failed++;System.out.println("FAIL "+name+": "+error);}finally{Thread.interrupted();}}
 static Object call(Class<?> type,String name,Class<?>[] args,Object...values)throws Exception {try{Method m=type.getDeclaredMethod(name,args);m.setAccessible(true);return m.invoke(null,values);}catch(NoSuchMethodException missing){throw new AssertionError("missing production deadline guard: "+type.getSimpleName()+"."+name);}catch(InvocationTargetException error){if(error.getCause() instanceof Exception)throw(Exception)error.getCause();throw(Error)error.getCause();}}
 static long after(long ms){return System.nanoTime()+ms*1_000_000L;}
 static InetAddress[] ips()throws Exception{return new InetAddress[]{InetAddress.getByAddress(new byte[]{8,8,4,4})};}
 static InetAddress[] dns(Callable<InetAddress[]> resolver,long deadline)throws Exception{return(InetAddress[])call(NetworkGuard.class,"resolvePublic",new Class[]{Callable.class,long.class},resolver,deadline);}
 static Exception rejects(Work work)throws Exception{try{work.run();throw new AssertionError("expected rejection");}catch(IOException error){return error;}}
 static class FakeSocket extends Socket {volatile boolean closed;int timeout;public synchronized void close(){closed=true;notifyAll();}public void setSoTimeout(int value){timeout=value;}}
 static AutoCloseable socketGuard(Class<?> type,Socket socket,long deadline)throws Exception{return(AutoCloseable)call(type,"guardSocket",new Class[]{Socket.class,long.class},socket,deadline);}
 public static void main(String[]args)throws Exception {
  group("DNS expires without releasing an unbounded worker backlog",()->{CountDownLatch release=new CountDownLatch(1);Callable<InetAddress[]> blocked=()->{for(;;)try{release.await();return ips();}catch(InterruptedException ignored){}};try{long start=System.nanoTime();Exception a=rejects(()->dns(blocked,after(45)));check(a instanceof SocketTimeoutException,"DNS wait is a typed timeout");Exception b=rejects(()->dns(blocked,after(45)));check(b instanceof SocketTimeoutException,"second fixed worker times out");Exception c=rejects(()->dns(blocked,after(500)));check(!(c instanceof SocketTimeoutException),"saturated resolver rejects instead of queueing");check((System.nanoTime()-start)/1_000_000L<700,"bounded waits and saturation finish promptly");}finally{release.countDown();}Thread.sleep(80);});
  group("DNS validates all public answers and preserves typed errors",()->{check(dns(SourceDeadlineTest::ips,after(500)).length==1,"normal DNS accepted");rejects(()->dns(()->new InetAddress[]{ips()[0],InetAddress.getByAddress(new byte[]{127,0,0,1})},after(500)));rejects(()->dns(()->new InetAddress[0],after(500)));rejects(()->dns(()->new InetAddress[]{null},after(500)));Exception typed=rejects(()->dns(()->{throw new UnknownHostException("fixture DNS");},after(500)));check(typed instanceof UnknownHostException,"unknown-host identity preserved");});
  group("expired and cancelled DNS do not invoke resolver",()->{int[] calls={0};Callable<InetAddress[]> resolver=()->{calls[0]++;return ips();};check(rejects(()->dns(resolver,System.nanoTime()-1)) instanceof SocketTimeoutException,"expired request rejected");Thread.currentThread().interrupt();try{check(rejects(()->dns(resolver,after(500))) instanceof InterruptedIOException,"pre-cancel rejected");check(Thread.currentThread().isInterrupted(),"cancellation remains set");}finally{Thread.interrupted();}check(calls[0]==0,"no DNS for expired/cancelled calls");});
  group("cancellation during DNS returns promptly and retains interruption",()->{CountDownLatch entered=new CountDownLatch(1);boolean[] result={false};Thread caller=new Thread(()->{try{dns(()->{entered.countDown();Thread.sleep(1000);return ips();},after(5000));}catch(Exception e){result[0]=e instanceof InterruptedIOException&&Thread.currentThread().isInterrupted();}});caller.start();check(entered.await(1,TimeUnit.SECONDS),"DNS began");caller.interrupt();caller.join(700);check(!caller.isAlive()&&result[0],"interrupted wait stopped");});
  for(Class<?> type:new Class[]{NetworkGuard.class,AppTransport.class}){
   group(type.getSimpleName()+" socket closes at shared total deadline",()->{FakeSocket socket=new FakeSocket();long start=System.nanoTime();try(AutoCloseable guard=socketGuard(type,socket,after(60))){synchronized(socket){while(!socket.closed)socket.wait(400);}}check(socket.closed,"watchdog closes stalled TLS/write/header/body socket");check((System.nanoTime()-start)/1_000_000L<500,"close is bounded by total deadline");});
   group(type.getSimpleName()+" cancellation closes active socket",()->{FakeSocket socket=new FakeSocket();Thread owner=Thread.currentThread();try(AutoCloseable guard=socketGuard(type,socket,after(5000))){owner.interrupt();long stop=after(500);while(!socket.closed&&System.nanoTime()<stop)Thread.onSpinWait();}finally{Thread.interrupted();}check(socket.closed,"interrupt watcher unblocks active IO");});
   group(type.getSimpleName()+" completed socket guard cancels timer",()->{FakeSocket socket=new FakeSocket();try(AutoCloseable guard=socketGuard(type,socket,after(60))){}Thread.sleep(110);check(!socket.closed,"closed guard does not later close reused owner socket");rejects(()->socketGuard(type,new FakeSocket(),System.nanoTime()-1));});
  }
  System.out.println("SOURCE_DEADLINE_"+(failed==0?"OK":"FAILED")+" groupsPassed="+passed+" groupsFailed="+failed+" checks="+checks+" networkRequests=0");if(failed>0)throw new AssertionError("source deadline regression gate failed");
 }
}
